"""Plain-text absence notices for parents."""

from typing import Iterable, List
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date

def _format_day(when: date) -> str:
    return f"{when:%B} {when.day}, {when.year}"

def _check_owner(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for {mark.student_id!r} does not belong to {student.student_id!r}"
            )

def _compose(student: Student, missed: List[date]) -> str:
    count = len(missed)
    noun = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    lines = "\n".join(f"- {_format_day(item)}" for item in missed)
    return f"Dear parent or guardian,\n\n{name} was absent for {count} {noun}:\n{lines}\n"

# ---
def build_absence_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Write a short notice listing the days the student was marked absent."""
    marks = list(marks)
    _check_owner(student, marks)
    missed = days_missed(marks)
    if not missed:
        raise ValueError(f"no absences to report for {student.student_id!r}")
    return _compose(student, missed)
